CREATE TABLE motus_word_bank (
  normalized TEXT PRIMARY KEY,
  word TEXT NOT NULL,
  frequency NUMERIC(12, 3) NOT NULL CHECK (frequency >= 0),
  CHECK (char_length(normalized) BETWEEN 5 AND 7),
  CHECK (normalized ~ '^[a-zæœ]+$'),
  CHECK (char_length(word) BETWEEN 5 AND 7),
  CHECK (word ~ '^[a-zàáâäãåæçèéêëìíîïñòóôöõœùúûüýÿ]+$')
);

ALTER TABLE motus_word_bank ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON motus_word_bank FROM PUBLIC, anon, authenticated;

